#!/usr/bin/env node
// fullstack / PreToolUse(Edit|Write|MultiEdit) — API 계약 보호
//   F1 (block) 생성된 파일 수정 금지: frontend.typesOut, 또는 첫 10줄에 "DO NOT EDIT / @generated / Generated by" 표시가 있는 파일
//   F2 (block) 계약 스냅샷(docs/api/openapi.json) 직접 수정 금지 — Stop 훅·/fullstack:spec 이 springdoc 결과로만 갱신
//   F3 (warn)  ErrorCode enum 상수 삭제·이름 변경 → 프론트(웹·iOS·Android) 사용처를 바로 보여줌
//   F4 (warn)  공통 응답 래퍼(ApiResponse·ErrorResponse·GlobalExceptionHandler) 변경 → 모든 API 에 영향
//   F5 (warn)  API 에 노출되는 enum 값 삭제·이름 변경 → DB 저장값·프론트 분기 마이그레이션 기록 요구
import path from 'node:path';
import { runHook, deny, pass } from '../lib/hook-io.mjs';
import { editContext, checkRules, blockMessage } from '../lib/rules-hook.mjs';
import { severityOf } from '../lib/code-rules.mjs';
import { logEvent } from '../lib/logger.mjs';
import { fsCfg, snapshotPath } from './contract.mjs';
import { FULLSTACK_RULES, hasGeneratedHeader } from './fs-rules.mjs';

await runHook(
  async (input) => {
    const ec = editContext(input);
    if (!ec) return pass();
    const fs = fsCfg(ec.cfg);
    // F1: 생성된 파일
    const sev1 = severityOf({ id: 'F1', severity: 'block' }, ec.cfg);
    if (sev1 === 'block') {
      const typesOut = fs.frontend && fs.frontend.typesOut ? path.resolve(ec.root, fs.frontend.typesOut) : null;
      const typesDir = typesOut ? path.dirname(typesOut) : null;
      const inTypes = typesOut && (ec.abs === typesOut || (/generated/i.test(typesDir) && ec.abs.startsWith(typesDir + path.sep)));
      if (inTypes || hasGeneratedHeader(ec.oldText)) {
        logEvent(ec.sessionRoot, ec.cfg, ec.sessionId, 'rule', { id: 'F1', severity: 'block', file: ec.rel });
        deny(`[F1] ${ec.rel} 는 자동 생성 파일이라 직접 고치지 않아요 — 다음 생성 때 덮어써져요. 원본(백엔드 API·명세)을 고친 뒤 /fullstack:api-sync 로 다시 생성하세요.`);
      }
    }
    // F2: 계약 스냅샷
    if (severityOf({ id: 'F2', severity: 'block' }, ec.cfg) === 'block' && fs.role === 'backend' && path.resolve(ec.abs) === path.resolve(snapshotPath(ec.root, fs))) {
      logEvent(ec.sessionRoot, ec.cfg, ec.sessionId, 'rule', { id: 'F2', severity: 'block', file: ec.rel });
      deny(`[F2] ${ec.rel} 는 springdoc 이 만든 API 계약 스냅샷이에요. 직접 고치지 말고 Controller·DTO 를 고친 뒤 /fullstack:spec 으로 다시 생성하세요.`);
    }
    // F3~F5
    const r = checkRules({ ...ec }, FULLSTACK_RULES.map((rule) => ({ ...rule, check: (t, c) => rule.check(t, { ...c, oldText: ec.oldText }) })), 'fullstack');
    if (r && r.blocks.length) deny(blockMessage(ec, r.blocks));
    return pass();
  },
  { failClosed: false, name: 'fullstack/pre-edit' },
);
